'use client'

import { Icon } from '@/registry/default/ui/icon'
import Image from 'next/image'
import FeatureBox from '@/registry/default/ui/feature-box'
import Link from 'next/link'
import InfoBadge from '@/registry/default/ui/info-badge'
import { cn } from '@/registry/default/lib/utils'

export default function SplitViewPanel({
     infoBadge,
     featureBox,
     imageUrl,
     description,
     title,
}: {
     infoBadge: any[]
     featureBox: any[]
     imageUrl: string
     description: string
     title: string
}) {
     return (
          <div
               className={cn(
                    'mx-3 min-h-[30rem] max-w-7xl overflow-hidden md:mx-5 lg:mx-7 xl:mx-auto'
               )}
               data-aos="fade-up"
          >
               <div className={cn('grid h-full w-full grid-cols-1 gap-5 lg:grid-cols-2 lg:gap-10')}>
                    {/* Left Side - Image */}
                    <div className={cn('h-full w-full')} data-aos="fade-right" data-aos-delay="100">
                         <div className={cn('relative')}>
                              <Image
                                   src={imageUrl}
                                   alt={title}
                                   width={1000}
                                   height={1000}
                                   className={cn(
                                        'h-full w-full rounded-xl object-cover object-bottom-right shadow-xl md:rounded-xl lg:min-h-[30rem] lg:rounded-3xl'
                                   )}
                              />
                              <div
                                   className={cn(
                                        'absolute top-1.5 left-1.5 space-y-1 md:top-4 md:left-4 md:space-y-2'
                                   )}
                              >
                                   {infoBadge.map((tag, index) => (
                                        <InfoBadge
                                             key={index}
                                             title={tag.title}
                                             iconColor={tag.iconColor}
                                             iconName={tag.iconName}
                                        />
                                   ))}
                              </div>
                         </div>
                    </div>

                    {/* Right Side - Content */}
                    <div
                         className={cn('flex w-full flex-col items-start justify-around space-y-6')}
                         data-aos="fade-left"
                         data-aos-delay="300"
                    >
                         <div className={cn('flex flex-col gap-5')}>
                              <h2
                                   className={cn(
                                        'text-base font-bold uppercase md:text-2xl lg:text-3xl'
                                   )}
                              >
                                   {title}
                              </h2>
                              <p
                                   className={cn(
                                        'text-xs text-gray-600 md:text-sm dark:text-gray-300'
                                   )}
                              >
                                   {description}
                              </p>

                              <div className={cn('grid grid-cols-1 gap-4 md:grid-cols-2')}>
                                   {/* Feature Box */}
                                   {featureBox.map((service, index) => (
                                        <FeatureBox
                                             key={index}
                                             title={service.title}
                                             description={service.description}
                                             iconColor={service.iconColor}
                                        />
                                   ))}
                              </div>
                         </div>

                         {/* Request Custom Service Button */}
                         <Link
                              href="/"
                              className={cn(
                                   'group flex w-fit items-center justify-start gap-2 rounded-full bg-orange-500 px-4 py-2 font-medium text-white transition-colors hover:bg-orange-600'
                              )}
                         >
                              <p className={cn('text-xs md:text-sm')}>Request Custom Service</p>
                              <Icon
                                   name="ArrowRight"
                                   className={cn(
                                        'h-3 w-3 transition-all duration-200 group-hover:translate-x-1 group-hover:rotate-[-45deg] md:h-4 md:w-4'
                                   )}
                              />
                         </Link>
                    </div>
               </div>
          </div>
     )
}

import { Icon } from '@/registry/default/ui/icon'
import { cva } from 'class-variance-authority'
import { cn } from '@/registry/default/lib/utils'

export const infoBadgeIconVariants = cva(
     'h-3 w-3 rounded-full border-2 md:border-3 md:h-4 md:w-4',
     {
          variants: {
               variant: {
                    orange: 'border-orange-500 bg-orange-500',
                    red: 'border-red-500 bg-red-500',
                    green: 'border-green-500 bg-green-500',
                    blue: 'border-blue-500 bg-blue-500',
               },
          },
          defaultVariants: {
               variant: 'orange',
          },
     }
)

export default function InfoBadge({
     title,
     iconColor,
     iconName,
}: {
     title: string
     iconColor:
          | 'orange'
          | 'red'
          | 'green'
          | 'blue'
          | 'yellow'
          | 'purple'
          | 'pink'
          | 'gray'
          | 'brown'
          | 'black'
          | 'white'
     iconName: 'Circle' | 'Check' | 'X' | 'Info'
}) {
     return (
          <div
               className={cn(
                    'md:py-1.5backdrop-blur-sm flex items-center gap-2 rounded-full bg-white/30 px-2 py-1.5'
               )}
          >
               <Icon
                    name={iconName}
                    className={cn(
                         infoBadgeIconVariants({
                              variant: iconColor as 'orange' | 'red' | 'green' | 'blue',
                         })
                    )}
               />
               <p className={cn('text-xs font-medium text-white/90')}>{title}</p>
          </div>
     )
}

import React from 'react'
import { getIcon, hasIcon, type IconName } from '@/registry/default/lib/icons'
import { cn } from '@/registry/default/lib/utils'

interface IconProps {
     name: IconName
     className?: string
     size?: number | string
     [key: string]: any // Allow passing through other props to the icon component
}

export function Icon({ name, className, size = 24, ...props }: IconProps) {
     if (typeof name !== 'string') {
          console.warn(`Icon name must be a string, got:`, name)
          return null
     }

     if (!hasIcon(name)) {
          console.warn(`Icon "${name}" not found in icon registry`)
          return null
     }

     const IconComponent = getIcon(name)

     if (!IconComponent) {
          return null
     }

     return <IconComponent className={cn(className)} size={size} {...props} />
}

// Export the icon registry for direct access if needed
export { iconMap, getIcon, hasIcon, type IconName } from '@/lib/icons'
